solution.code:
public class Main {
    static long reverse(int n) {
        long reversed = 0;
        while (n > 0) {
            reversed = reversed * 10 + n % 10;
            n /= 10;
        }
        return reversed;
    }

    public static void main(String[] args) {
        System.out.println(reverse(1534236469));
    }
}
